import pytest
from rpn import eval_rpn


@pytest.mark.parametrize("expr,val", [("3 4 +", 7.0), ("5 1 2 + 4 * + 3 -", 14.0),
                                      ("2 3 ^", 8.0), ("-3 2 *", -6.0), ("7 2 /", 3.5),
                                      ("1.5 2 *", 3.0), ("42", 42.0)])
def test_validas(expr, val):
    assert eval_rpn(expr) == pytest.approx(val)
    assert isinstance(eval_rpn(expr), float)


@pytest.mark.parametrize("bad", ["", "+", "1 +", "1 2", "1 2 x", "1 2 % "])
def test_invalidas(bad):
    with pytest.raises(ValueError):
        eval_rpn(bad)


def test_division_por_cero():
    with pytest.raises(ZeroDivisionError):
        eval_rpn("1 0 /")


def test_no_usa_eval():
    import inspect, rpn
    src = inspect.getsource(rpn)
    assert "eval(" not in src.replace("eval_rpn(", "")

