import operator

_OPS = {"+": operator.add, "-": operator.sub, "*": operator.mul,
        "/": operator.truediv, "^": operator.pow}


def eval_rpn(expr):
    tokens = expr.split()
    if not tokens:
        raise ValueError("vacia")
    stack = []
    for t in tokens:
        if t in _OPS:
            if len(stack) < 2:
                raise ValueError("pila insuficiente")
            b, a = stack.pop(), stack.pop()
            stack.append(float(_OPS[t](a, b)))
        else:
            try:
                stack.append(float(t))
            except ValueError:
                raise ValueError(f"token desconocido: {t}") from None
    if len(stack) != 1:
        raise ValueError("sobran operandos")
    return stack[0]
